from itertools import combinations

def simulate(k, initial_config):
    config = list(initial_config)
    visited = set()
    while config not in visited:
        visited.add(tuple(config))
        n = len(config)
        # find the block containing the k-th coin (1-indexed)
        idx = k - 1
        coin = config[idx]

        # find the largest block of same coins containing idx
        left = idx
        while left > 0 and config[left-1] == coin:
            left -= 1
        right = idx
        while right < n - 1 and config[right+1] == coin:
            right += 1

        block = config[left:right+1]
        new_config = block + config[:left] + config[right+1:]
        config = new_config

    # Check if at most one adjacency
    adjacencies = 0
    for i in range(len(config) - 1):
        if config[i] != config[i+1]:
            adjacencies += 1
    return adjacencies <= 1

def check_k(n_a, n_c, k):
    configs = []
    for combo in combinations(range(n_a + n_c), n_a):
        config = ['A' if i in combo else 'C' for i in range(n_a + n_c)]
        configs.append(config)

    for config in configs:
        if not simulate(k, config):
            return False
    return True

for n_a, n_c in [(2, 2), (3, 3), (4, 4)]:
    results = {}
    for k in range(1, n_a + n_c + 1):
        results[k] = check_k(n_a, n_c, k)
    print(f"n={n_a+n_c}: {results}")

